// Types for the product catalog. Must match src/data/catalog.json,
// generated by scripts/build-catalog.mjs from catalog/catalog.csv.

export interface Variant {
  sku: string;
  /** Display label for the variant option (e.g. "25 cm", "Media luna"). */
  label: string;
  /** Number of pieces in a pack. null if sold individually. */
  piecesPerPack: number | null;
  /** Base price per piece (plant list). null when quoted on request. */
  basePrice: number | null;
  /** Sale price per piece, or null if not on sale. */
  salePrice: number | null;
  /**
   * Displayed price per piece (salePrice if set, otherwise basePrice).
   * null when quoted on request — always narrow it before formatting, because
   * Intl.NumberFormat prints null as "$0.00" instead of throwing.
   */
  currentPrice: number | null;
  /** true only when salePrice < basePrice (real discount, shown crossed out). */
  onSale: boolean;
  /** Total pack price (currentPrice * piecesPerPack), or null. */
  packPrice: number | null;
  /**
   * true when the client has not confirmed a price yet. The UI must show
   * "Consulta precio" and the variant must never enter the cart.
   */
  quoteOnRequest: boolean;
  priceUnit: string;
  /** Variant-specific description, falling back to the family description. */
  description: string;
  /** Individual variant image, or null if only the family image is available. */
  variantImage: string | null;
  /** Colors the customer can choose (do not affect price or SKU). */
  availableColors: string[];
  isNew: boolean;
  available: boolean;
}

export interface Family {
  id: string;
  product: string;
  category: string;
  material: string;
  colors: string;
  description: string;
  image: string;
  isNew: boolean;
  variants: Variant[];
}

export interface Catalog {
  generatedAt: string;
  currency: string;
  categories: string[];
  families: Family[];
}
